using System.Linq;using UnityEngine;using EternalSteam.OpenWorld;using Newtonsoft.Json.Linq;
public static class InspectHud08Text{public static string Main(){var h=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>();return new JArray(h.Sandbox.PauseMenu.Panel.GetComponentsInChildren<TMPro.TMP_Text>(true).Select(t=>new JObject{{"name",t.name},{"font",t.fontSize},{"auto",t.enableAutoSizing},{"scale",t.transform.lossyScale.ToString()},{"parentScale",t.transform.parent.localScale.ToString()},{"local",t.transform.localScale.ToString()},{"layout",h.Layout.Texts.Contains(t)}})).ToString();}}
